/* Compact reports retain the existing calculation rules. */
const reportSections=['food','weight','sleep','habits','moments','method'];
function reportPanel(id,title,caption,content){
 const ui=ixState();ui.openSections||={};
 return `<details class="report-panel" data-report-section="${id}" ${ui.openSections[id]?'open':''}><summary><span><strong>${title}</strong><small>${esc(caption)}</small></span><span class="disclosure-mark" aria-hidden="true">＋</span></summary><div class="report-panel-body stack">${content}</div></details>`;
}
function reportView(){
 const ui=ixState(),dates=ixReportRange();
 const controls=`<div class="progress-tabs" role="group" aria-label="Период отчёта">${[7,30,90].map(n=>`<button class="button ${n===ui.period?'':'secondary'}" data-action="report-period" data-period="${n}" aria-pressed="${n===ui.period}">${n} дней</button>`).join('')}</div>${field('report-end','Последний день периода',ui.end,`type="date" min="${MIN_DATE}" max="${TODAY}" aria-describedby="report-error"`)}`;
 if(!dates)return `<div class="screen report-screen">${header('home','Мой отчёт')}${controls}<p class="error" id="report-error" role="alert">Выберите дату не позднее ${dateLabel(TODAY)}.</p></div>`;
 const start=calendarDay(dates[0]),previousDates=start>calendarDay(MIN_DATE)?ixDates(dateFromDay(start-1),ui.period):[];
 const data=ixAggregate(dates),prev=ixAggregate(previousDates),food=data.food[0],period=dateLabel(dates[0])+' — '+dateLabel(dates.at(-1));
 const weight=data.weight.mean===null?'—':weightText(data.weight.mean)+' кг',sleep=data.sleep.mean===null?'—':sleepText(data.sleep.mean);
 const diff=(a,b,f)=>`<p class="small">${ixDifference(a,b,f)}</p>`;
 const foodBody=`<p class="report-value" id="report-food-mean">${food.text}${food.mean===null?'':' ккал / день'}</p><p class="small muted">Среднее по заполненным дням: N = ${data.complete} / ${dates.length}. Подтверждённый ноль входит, частичные дни и пропуски — нет.</p><div class="nutrition">${['Белки','Жиры','Углеводы'].map((n,i)=>`<div><strong>${data.food[i+1].text}</strong><small>${n}, г</small></div>`).join('')}</div>${diff(food.mean,prev.food[0].mean,n=>fmt(n)+' ккал')}${ixMiniChart(data.rows,'food','Питание по заполненным дням')}<button class="link" data-action="report-chart" data-metric="food">Подробное питание и цели →</button><h3>Часто в дневнике</h3><p class="small muted">Все внесённые порции, включая частичные дни. Частота не оценивает пользу.</p>${data.top.length?data.top.map((item,i)=>`<div class="row report-top"><span class="pill">${i+1}</span><strong class="grow">${esc(item.name)}</strong><span class="small">${item.count} зап.<br>${item.dates.size} дн.</span></div>`).join(''):'<p class="small muted">Пока нет записей еды.</p>'}`;
 const weightBody=`<p class="report-value" id="report-weight-mean">${weight}</p><p class="small muted">N = ${data.weight.count} / ${dates.length} дн.</p>${diff(data.weight.mean,prev.weight.mean,n=>weightText(n)+' кг')}${ixMiniChart(data.rows,'weight','Измерения веса')}<button class="link" data-action="report-chart" data-metric="weight">Точные значения и даты →</button>`;
 const sleepBody=`<p class="report-value" id="report-sleep-mean">${sleep}</p><p class="small muted">N = ${data.sleep.count} / ${dates.length} дн. Подтверждённый нулевой сон входит в выборку.</p>${diff(data.sleep.mean,prev.sleep.mean,sleepText)}${ixMiniChart(data.rows,'sleep','Записи сна')}<button class="link" data-action="report-chart" data-metric="sleep">Открыть подробный график →</button>`;
 const habitsBody=`<h3>Насколько полная картина</h3>${ixCoverage('Питание · заполненные дни',data.complete,dates.length)}${ixCoverage('Вес · дни с измерением',data.weight.count,dates.length)}${ixCoverage('Сон · дни с записью',data.sleep.count,dates.length)}<p class="small muted">Питание: частично ${data.partial}, без записей ${data.missing}. Каждый показатель использует свою выборку.</p><h3>Карта ведения дневника</h3><p class="small muted">Акцентная ячейка — питание заполнено; приглушённая — есть другие записи; пустая — записей нет. Цвет не оценивает результат.</p><div class="report-heatmap">${data.rows.map(r=>`<button class="heat-day ${ixHasRecord(r.record)?'has-record':''} ${ixFoodStatus(r.record)==='complete'?'food-complete':''}" data-action="insight-open-day" data-date="${r.date}" aria-label="${esc(ixDayLabel(r.date))}">${Number(r.date.slice(8))}</button>`).join('')}</div><button class="link" data-action="calendar">Открыть календарь →</button>`;
 const methodBody=`<p class="small muted">Основной период: ${period}. Предыдущий: ${previousDates.length?dateLabel(previousDates[0])+' — '+dateLabel(previousDates.at(-1)):'недоступен'}. Сравниваются средние каждого показателя по собственной выборке.</p><p class="small muted">Предыдущие выборки: вес N=${prev.weight.count}, сон N=${prev.sleep.count}, заполненное питание N=${prev.complete}. Округление: вес до 0,01 кг, сон до минуты, питание до 0,1. Отсутствие записи не заменяется нулём. План и шаблоны не входят в фактический отчёт.</p><p class="small muted">Исторические цели и таблицы дат доступны в подробных графиках. Отчёт описывает записи и не даёт медицинских заключений.</p>`;
 return `<div class="screen report-screen compact-report">${header('home','Мой отчёт','Краткая картина. Подробности — по вашему выбору.')}<section class="report-hero stack"><span class="eyebrow">${data.active?'Дней с записями: '+data.active:'Начало вашей истории'}</span><p class="small">${period}</p><div class="report-glance"><div><strong>${food.text}</strong><small>ккал · N=${data.complete}</small></div><div><strong>${weight}</strong><small>вес · N=${data.weight.count}</small></div><div><strong>${sleep}</strong><small>сон · N=${data.sleep.count}</small></div></div></section>${controls}<p class="error" id="report-error" role="alert"></p>${data.active?'':'<p class="notice">Пока нет записей за период. Добавьте еду, вес, сон или личные моменты.</p>'}<div class="row wrap report-disclosure-controls"><button class="link" data-action="report-expand">Развернуть всё</button><button class="link" data-action="report-collapse">Свернуть всё</button></div><div class="stack report-sections">${reportPanel('food','Питание',food.text+' ккал · заполнено '+data.complete+' / '+dates.length+' дн.',foodBody)}${reportPanel('weight','Вес',weight+' · N='+data.weight.count,weightBody)}${reportPanel('sleep','Сон',sleep+' · N='+data.sleep.count,sleepBody)}${reportPanel('habits','Привычки и полнота','Карта дней и отдельные выборки',habitsBody)}${reportPanel('moments','Личные моменты','Фотографии, настроение и заметки',ixMomentsReport(data.rows))}${reportPanel('method','Как посчитано','Правила, периоды и округление',methodBody)}</div></div>`;
}
function reportPanelsAction(a){
 if(!['report-expand','report-collapse'].includes(a))return false;
 ixState().openSections=Object.fromEntries(reportSections.map(id=>[id,a==='report-expand']));render();return true;
}
document.addEventListener('toggle',event=>{
 const el=event.target;if(el.matches?.('[data-report-section]')&&state?.screen==='report'){ixState().openSections||={};ixState().openSections[el.dataset.reportSection]=el.open;}
},true);
